pub fn equilibrate(
        &mut self,
        gravity: DVec3,
        max_iterations: usize,
    ) -> Result<f64, TissueError> {
        if !gravity.is_finite() || !(1..=4096).contains(&max_iterations) {
            return Err(TissueError::InvalidInput("equilibrium parameters"));
        }
        let mut x = self.positions.clone();
        let objective = |x: &[DVec3]| {
            self.objective(x, &self.positions, self.frame, f64::INFINITY)
                - x.iter()
                    .zip(&self.positions)
                    .zip(&self.masses)
                    .map(|((x, p), m)| m * gravity.dot(*x - *p))
                    .sum::<f64>()
        };
        for _ in 0..max_iterations {
            let mut system = self.linearize(&x, &self.positions, self.frame, f64::INFINITY);
            for (i, g) in system.gradient.iter_mut().enumerate() {
                if self.inverse_mass[i] > 0.0 {
                    *g -= self.masses[i] * gravity;
                }
            }
            let residual = system
                .gradient
                .iter()
                .map(|g| g.length())
                .fold(0.0, f64::max);
            if residual < 2e-5 {
                self.positions = x;
                self.velocities.fill(DVec3::ZERO);
                return Ok(residual);
            }
            let delta = system.direction();
            x = self.descend(&x, &delta, dot(&system.gradient, &delta), &objective)?;
        }
        Err(TissueError::InvalidInput("equilibrium did not converge"))
    }type Err = anyhow::Errorfn dot(a: &[DVec3], b: &[DVec3]) -> f64fn direction(&self) -> Vec<DVec3>fn descend( &self, x: &[DVec3], delta: &[DVec3], slope: f64, objective: impl Fn(&[DVec3]) -> f64, ) -> Result<Vec<DVec3>, TissueError>fn linearize(&self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64) -> Systemfn objective(&self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64) -> f64

pub fn validate(&self) -> anyhow::Result<()> {
        anyhow::ensure!(
            self.schema_version == 1
                && (1..=8).contains(&self.regions.len())
                && (1..=64).contains(&self.surfaces.len()),
            "unsupported tissue asset version or size"
        );
        let mut names = BTreeSet::new();
        for region in &self.regions {
            anyhow::ensure!(
                !region.name.is_empty()
                    && !region.anchor_bone.is_empty()
                    && names.insert(&region.name),
                "missing or duplicate tissue region"
            );
            anyhow::ensure!(
                region
                    .attachments
                    .iter()
                    .filter(|a| matches!(a, Attachment::Fixed))
                    .count()
                    >= 3,
                "tissue requires a distributed fixed attachment footprint"
            );
            region.solver(Frame::IDENTITY)?;
        }
        let mut hashes = BTreeSet::new();
        for surface in &self.surfaces {
            anyhow::ensure!(
                surface.positions_sha256.len() == 64
                    && surface
                        .positions_sha256
                        .bytes()
                        .all(|b| b.is_ascii_hexdigit())
                    && hashes.insert(&surface.positions_sha256),
                "invalid or duplicate tissue surface hash"
            );
            anyhow::ensure!(
                (1..=1_000_000).contains(&surface.vertex_count)
                    && !surface.vertices.is_empty()
                    && surface.vertices.len() <= 100_000,
                "tissue surface capacity"
            );
            self.validate_bindings(surface)?;
        }
        Ok(())
    }pub fn solver(&self, frame: Frame) -> Result<Tissue, TissueError>fn validate_bindings(&self, surface: &SurfaceBinding) -> anyhow::Result<()>

pub struct TissueAsset {
    pub schema_version: u32,
    pub regions: Vec<RegionAsset>,
    pub surfaces: Vec<SurfaceBinding>,
}

pub fn body_soft_physics(&self) -> Option<&Cc5SoftPhysics> {
        for (mesh, sp) in &self.soft_physics_by_mesh {
            let n = mesh.to_lowercase();
            if n.contains("body") || n.contains("skin") || n.contains("torso") {
                return Some(sp);
            }
        }
        None
    }
